415	/// A subgradient for conic gradients.
416	#[derive(Clone, Hash)]
417	pub struct SVGSubGradient {
418	    /// The center point of the gradient.
419	    center: Axes<Ratio>,
420	    /// The start point of the subgradient.
421	    t0: Angle,
422	    /// The end point of the subgradient.
423	    t1: Angle,
424	    /// The color at the start point of the subgradient.
425	    c0: Color,
426	    /// The color at the end point of the subgradient.
427	    c1: Color,
428	}
429	
430	/// The kind of linear gradient.
431	#[derive(Copy, Clone, Eq, PartialEq, Hash)]
432	enum GradientKind {
433	    /// A linear gradient.
434	    Linear,
435	    /// A radial gradient.
436	    Radial,
437	    /// A conic gradient.
438	    Conic,
439	}
