441	impl From<&Gradient> for GradientKind {
442	    fn from(value: &Gradient) -> Self {
443	        match value {
444	            Gradient::Linear { .. } => GradientKind::Linear,
445	            Gradient::Radial { .. } => GradientKind::Radial,
446	            Gradient::Conic { .. } => GradientKind::Conic,
447	        }
448	    }
